True from collections import Counter

def transform(grid):
    # Move every non-background cell down one row.
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg for _ in row] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != bg and r + 1 < len(grid):
                out[r + 1][c] = value
    return out
